using praenora::detail::SchemaIssue;
using praenora::detail::SchemaRegistry;
using praenora::test::ScratchDir;

namespace {

const json kSample = json::parse(R"({
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "required": ["name"],
  "properties": {
    "name": {"type": "string"},
    "gain": {"type": "number", "minimum": 0, "maximum": 1, "default": 0.5},
    "options": {
      "type": "object",
      "properties": {"retries": {"type": "integer", "default": 3}},
      "additionalProperties": false
    }
  },
  "additionalProperties": false
})");

template <typename Fn> ErrorCode error_code_of(Fn&& fn) {
    try {
        fn();
    } catch (const Error& e) {
        return e.code();
    }
    return ErrorCode::OK;
}

std::string read_bytes(const fs::path& path) {
    std::ifstream in(path, std::ios::binary);
    return std::string(std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>());
}

void write_file(const fs::path& path, const std::string& text) {
    std::ofstream out(path, std::ios::binary);
    out << text;
}

} // namespace

TEST(Schema, ValidReturnsNoIssues) {
    const CompiledSchema schema(kSample, "sample");
    EXPECT_EQ(schema.name(), "sample");
    EXPECT_TRUE(schema.validate(json::parse(R"({"name":"x","gain":0.25})")).empty());
    EXPECT_TRUE(schema.validate(json::parse(R"({"name":"x","options":{"retries":1}})")).empty());
}

TEST(Schema, InvalidReturnsPointersAndMessages) {
    const CompiledSchema schema(kSample, "sample");
    const auto issues = schema.validate(json::parse(R"({"name":"x","gain":-1})"));
    ASSERT_EQ(issues.size(), 1u);
    EXPECT_EQ(issues[0].pointer, "/gain");
    EXPECT_NE(issues[0].message.find("below minimum"), std::string::npos) << issues[0].message;

    // Every problem is collected, not only the first.
    const auto many = schema.validate(json::parse(R"({"gain":"high","options":{"retries":1.5}})"));
    std::set<std::string> pointers;
    for (const auto& issue : many) {
        pointers.insert(issue.pointer);
        EXPECT_FALSE(issue.message.empty());
    }
    EXPECT_EQ(pointers, (std::set<std::string>{"", "/gain", "/options/retries"}));

    // A property that `additionalProperties` forbids is reported at the property itself.
    const auto unknown =
        schema.validate(json::parse(R"({"name":"x","extra":1,"options":{"x/y":2}})"));
    ASSERT_EQ(unknown.size(), 2u);
    EXPECT_EQ(unknown[0].pointer, "/extra");
    EXPECT_EQ(unknown[0].message, "property 'extra' is not allowed");
    EXPECT_EQ(unknown[1].pointer, "/options/x~1y");

    const auto root = schema.validate(json::parse("[1, 2]"));
    ASSERT_FALSE(root.empty());
    EXPECT_EQ(root[0].pointer, "");
}

TEST(Schema, DefaultsApplied) {
    const CompiledSchema schema(kSample, "sample");
    std::vector<SchemaIssue> issues;
    const auto completed = schema.apply_defaults(json::parse(R"({"name":"x"})"), issues);
    EXPECT_TRUE(issues.empty());
    EXPECT_EQ(completed.at("gain"), json(0.5));
    EXPECT_EQ(completed.at("name"), json("x"));

    // Given values are kept; defaults of nested objects that are present are filled in.
    const auto nested =
        schema.apply_defaults(json::parse(R"({"name":"x","gain":0.9,"options":{}})"), issues);
    EXPECT_TRUE(issues.empty());
    EXPECT_EQ(nested.at("gain"), json(0.9));
    EXPECT_EQ(nested.at("options").at("retries"), json(3));

    // Problems are reported through `issues`.
    schema.apply_defaults(json::parse(R"({"gain":2})"), issues);
    EXPECT_EQ(issues.size(), 2u);
}

TEST(Schema, InvalidSchemaThrowsSchemaViolation) {
    const std::vector<std::string> bad = {
        R"({"type": "numbr"})",
        R"({"type": 5})",
        R"({"minimum": "zero"})",
        R"({"properties": []})",
        R"({"required": "name"})",
        R"({"pattern": "("})",
        R"({"$ref": "#/definitions/missing"})",
        R"({"$ref": "http://example.com/other.json"})",
        R"({"$ref": "urn:praenora:schema:no-such-kind:0.1"})",
        R"({"$schema": "https://json-schema.org/draft/2020-12/schema", "type": "object"})",
        R"({"$id": 7})",
        R"(42)",
        R"("object")",
    };
    for (const auto& text : bad) {
        SCOPED_TRACE(text);
        EXPECT_EQ(error_code_of([&] { CompiledSchema(json::parse(text), "bad"); }),
                  ErrorCode::SCHEMA_VIOLATION);
    }
    try {
        CompiledSchema(json::parse(R"({"type": "object", "properties": {"a": {"type": "numbr"}}})"),
                       "params");
        FAIL() << "no error";
    } catch (const Error& e) {
        EXPECT_NE(std::string(e.what()).find("params"), std::string::npos) << e.what();
        EXPECT_EQ(e.location().pointer, "/properties/a");
    }
}

TEST(Schema, UrnIdAccepted) {
    const auto schema_json = json::parse(R"({
      "$schema": "http://json-schema.org/draft-07/schema",
      "$id": "urn:praenora:schema:sample:0.1",
      "type": "object",
      "properties": {"gain": {"$ref": "#/definitions/fraction"}},
      "definitions": {"fraction": {"type": "number", "minimum": 0, "maximum": 1}}
    })");
    const CompiledSchema schema(schema_json, "sample@0.1");
    EXPECT_TRUE(schema.validate(json::parse(R"({"gain":0.5})")).empty());
    const auto issues = schema.validate(json::parse(R"({"gain":1.5})"));
    ASSERT_EQ(issues.size(), 1u);
    EXPECT_EQ(issues[0].pointer, "/gain");
}

TEST(Schema, BooleanSchemasAndDraft07MetaSchemaReference) {
    EXPECT_TRUE(CompiledSchema(json(true), "any").validate(json::parse("[1]")).empty());
    EXPECT_FALSE(CompiledSchema(json(false), "none").validate(json::parse("1")).empty());
    // A schema may describe schemas by referring to the draft-07 meta-schema.
    const CompiledSchema schemas(
        json::parse(R"({"$ref": "http://json-schema.org/draft-07/schema#"})"), "schema");
    EXPECT_TRUE(schemas.validate(kSample).empty());
    EXPECT_FALSE(schemas.validate(json::parse(R"({"type": "numbr"})")).empty());
}

TEST(Schema, FormatsAreCheckedWhenSupported) {
    const CompiledSchema date_time(json::parse(R"({"type":"string","format":"date-time"})"), "dt");
    EXPECT_TRUE(date_time.validate(json("2026-11-10T16:04:05.123456789Z")).empty());
    EXPECT_FALSE(date_time.validate(json("yesterday")).empty());
    // A format the validator does not implement is accepted (formats are annotations then).
    const CompiledSchema reference(json::parse(R"({"type":"string","format":"uri-reference"})"),
                                   "ref");
    EXPECT_TRUE(reference.validate(json("a/b#c")).empty());
}

TEST(Schema, ConcurrentValidationIsSafe) {
    const CompiledSchema schema(kSample, "sample");
    std::vector<std::thread> threads;
    std::vector<int> failures(8, 0);
    for (std::size_t t = 0; t < failures.size(); ++t) {
        threads.emplace_back([&, t] {
            for (int i = 0; i < 200; ++i) {
                if (!schema.validate(json::parse(R"({"name":"x","gain":0.5})")).empty() ||
                    schema.validate(json::parse(R"({"gain":-1})")).size() != 2) {
                    ++failures[t];
                }
            }
        });
    }
    for (auto& thread : threads) {
        thread.join();
    }
    for (const int f : failures) {
        EXPECT_EQ(f, 0);
    }
}

TEST(SchemaRegistry, FromDirectorySelectsByFormatVersion) {
    const auto registry =
        SchemaRegistry::from_directory(praenora::test::fixture_path("documents/schema-registry"));
    const auto& v01 = registry.for_kind("sample", parse_semver("0.1.7"));
    EXPECT_EQ(v01.name(), "sample@0.1");
    EXPECT_NE(registry.text_for_kind("sample", parse_semver("0.1.0"))
                  .find("urn:praenora:schema:sample:0.1"),
              std::string_view::npos);
    // 0.1 has no "mode"; 0.2 adds it with a default.
    std::vector<SchemaIssue> issues;
    EXPECT_FALSE(v01.validate(json::parse(R"({"name":"x","mode":"fast"})")).empty());
    const auto& v02 = registry.for_kind("sample", parse_semver("0.2.0-rc.1"));
    EXPECT_EQ(v02.name(), "sample@0.2");
    const auto completed = v02.apply_defaults(json::parse(R"({"name":"x"})"), issues);
    EXPECT_TRUE(issues.empty());
    EXPECT_EQ(completed.at("mode"), json("exact"));
    EXPECT_EQ(completed.at("gain"), json(0.5)) << "defaults are found through $ref";

    // The same compiled schema is returned every time.
    EXPECT_EQ(&registry.for_kind("sample", parse_semver("0.1.0")), &v01);

    EXPECT_EQ(error_code_of([&] { registry.for_kind("sample", parse_semver("0.3.0")); }),
              ErrorCode::FORMAT_VERSION_UNSUPPORTED);
    EXPECT_EQ(error_code_of([&] { registry.for_kind("sample", parse_semver("1.1.0")); }),
              ErrorCode::FORMAT_VERSION_UNSUPPORTED);
    EXPECT_EQ(error_code_of([&] { registry.for_kind("other", parse_semver("0.1.0")); }),
              ErrorCode::FORMAT_VERSION_UNSUPPORTED);
    EXPECT_EQ(error_code_of([&] { registry.text_for_kind("sample", parse_semver("0.3.0")); }),
              ErrorCode::FORMAT_VERSION_UNSUPPORTED);
}

TEST(SchemaRegistry, EntriesAreSortedByKindAndVersion) {
    const auto registry =
        SchemaRegistry::from_directory(praenora::test::fixture_path("documents/schema-registry"));
    const auto entries = registry.entries();
    ASSERT_EQ(entries.size(), 2u);
    EXPECT_EQ(entries[0].first, "sample");
    EXPECT_EQ(praenora::detail::to_string(entries[0].second), "0.1.0");
    EXPECT_EQ(praenora::detail::to_string(entries[1].second), "0.2.0");
}

TEST(SchemaRegistry, SchemaIdMustMatchItsFileName) {
    ScratchDir dir;
    write_file(dir.path() / "other.0.1.schema.json",
               R"({"$id": "urn:praenora:schema:sample:0.1", "type": "object"})");
    write_file(dir.path() / "broken.0.1.schema.json", "{ not json");
    write_file(dir.path() / "anonymous.0.1.schema.json", R"({"type": "object"})");
    write_file(dir.path() / "notes.txt", "ignored");
    write_file(dir.path() / "Bad_Name.0.1.schema.json", "{}");
    const auto registry = SchemaRegistry::from_directory(dir.path());
    EXPECT_EQ(registry.entries().size(), 3u) << "only <kind>.<major>.<minor>.schema.json files";
    EXPECT_EQ(error_code_of([&] { registry.for_kind("other", parse_semver("0.1.0")); }),
              ErrorCode::SCHEMA_VIOLATION);
    EXPECT_EQ(error_code_of([&] { registry.for_kind("anonymous", parse_semver("0.1.0")); }),
              ErrorCode::SCHEMA_VIOLATION)
        << "a registry schema must have an $id";
    EXPECT_EQ(error_code_of([&] { registry.for_kind("broken", parse_semver("0.1.0")); }),
              ErrorCode::PARSE_ERROR);
    EXPECT_EQ(error_code_of([&] { SchemaRegistry::from_directory(dir.path() / "missing"); }),
              ErrorCode::IO_ERROR);
}

TEST(SchemaRegistry, ConcurrentFirstUseCompilesOnce) {
    const auto registry =
        SchemaRegistry::from_directory(praenora::test::fixture_path("documents/schema-registry"));
    std::vector<const CompiledSchema*> seen(8, nullptr);
    std::vector<std::thread> threads;
    for (std::size_t t = 0; t < seen.size(); ++t) {
        threads.emplace_back(
            [&, t] { seen[t] = &registry.for_kind("sample", parse_semver("0.2.0")); });
    }
    for (auto& thread : threads) {
        thread.join();
    }
    for (const auto* schema : seen) {
        EXPECT_EQ(schema, seen[0]);
    }
}

TEST(SchemaRegistry, BuiltinIndexesEmbeddedSchemas) {
    const auto& builtin = SchemaRegistry::builtin();
    EXPECT_EQ(&builtin, &SchemaRegistry::builtin());
    for (const auto& [kind, version] : builtin.entries()) {
        SCOPED_TRACE(kind);
        EXPECT_FALSE(builtin.text_for_kind(kind, version).empty());
        EXPECT_EQ(builtin.for_kind(kind, version).name(),
                  kind + "@" + std::to_string(version.major) + "." + std::to_string(version.minor));
    }
    EXPECT_EQ(error_code_of([&] { builtin.for_kind("no-such-kind", parse_semver("0.1.0")); }),
              ErrorCode::FORMAT_VERSION_UNSUPPORTED);
}

TEST(Resources, EmbeddedIndexListsPrefix) {
    const std::vector<std::string> both = {"schema-registry/sample.0.1.schema.json",
                                           "schema-registry/sample.0.2.schema.json"};
    EXPECT_EQ(praenora_test_list_resources("schema-registry/"), both);
    EXPECT_EQ(praenora_test_list_resources(""), both);
    EXPECT_EQ(praenora_test_list_resources("schema-registry/sample.0.2"),
              std::vector<std::string>{both[1]});
    EXPECT_TRUE(praenora_test_list_resources("catalog/").empty());

    for (const auto& path : both) {
        const auto bytes = praenora_test_find_resource(path);
        ASSERT_TRUE(bytes.has_value()) << path;
        EXPECT_EQ(std::string(*bytes),
                  read_bytes(praenora::test::fixture_path("documents/" + path)));
    }
    EXPECT_FALSE(praenora_test_find_resource("schema-registry/missing.json").has_value());
    EXPECT_FALSE(praenora_test_find_resource("schema-registry").has_value());
    EXPECT_FALSE(praenora_test_find_resource("").has_value());
}

TEST(Resources, RuntimeIndexIsConsistent) {
    for (const auto& path : praenora::detail::list_embedded_resources("")) {
        SCOPED_TRACE(path);
        EXPECT_TRUE(path.rfind("schemas/", 0) == 0 || path.rfind("catalog/", 0) == 0);
        const auto bytes = praenora::detail::find_embedded_resource(path);
        ASSERT_TRUE(bytes.has_value());
        EXPECT_FALSE(bytes->empty());
    }
    for (const auto& path : praenora::detail::list_embedded_resources("schemas/")) {
        EXPECT_EQ(path.rfind("schemas/", 0), 0u);
    }
    EXPECT_FALSE(praenora::detail::find_embedded_resource("schemas/no-such.0.1.schema.json"));
}
